import 'package:flutter/material.dart'; import '../core/theme.dart'; import '../models/anime.dart'; import '../services/anime_api.dart'; import '../widgets/anime_widgets.dart';
class AnimeDetailPage extends StatefulWidget{const AnimeDetailPage({super.key,required this.anime,required this.isSaved,required this.onSave,required this.onPlay});final Anime anime;final bool isSaved;final VoidCallback onSave;final ValueChanged<int> onPlay;@override State<AnimeDetailPage> createState()=>_AnimeDetailPageState();}
class _AnimeDetailPageState extends State<AnimeDetailPage>{late bool saved;String status='';@override void initState(){super.initState();saved=widget.isSaved;if(RegExp(r'^\\d+$').hasMatch(widget.anime.id)){AnimeApi.get('/api/info?anilistId=${widget.anime.id}').then((_){if(mounted)setState(()=>status='Metadata API connected');}).catchError((_){if(mounted)setState(()=>status='Using available information');});}}
void toggle(){setState(()=>saved=!saved);widget.onSave();}
@override Widget build(BuildContext c)=>Scaffold(body:CustomScrollView(slivers:[SliverAppBar(expandedHeight:320,pinned:true,actions:[IconButton(onPressed:toggle,icon:Icon(saved?Icons.bookmark:Icons.bookmark_border,color:appPurple))],flexibleSpace:FlexibleSpaceBar(background:Stack(fit:StackFit.expand,children:[AnimeCover(widget.anime.image),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.transparent,appBg]))),Positioned(left:18,bottom:20,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.anime.year,style:const TextStyle(color:appCyan)),Text(widget.anime.title,style:const TextStyle(fontSize:29,fontWeight:FontWeight.w900)),Text('★ ${widget.anime.score}')]))]))),SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[FilledButton.icon(onPressed:()=>widget.onPlay(1),icon:const Icon(Icons.play_arrow),label:const Text('Watch episode 1')),Text(status,style:const TextStyle(color:appMuted)),const SizedBox(height:18),const Text('Synopsis',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(widget.anime.synopsis.isEmpty?'Anime synopsis and metadata will load when provided by the API.':widget.anime.synopsis,style:const TextStyle(color:appMuted,height:1.5)),Wrap(children:widget.anime.genres.map((g)=>Chip(label:Text(g))).toList()),const Text('Episodes',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...List.generate(12,(i)=>Card(color:appPanel,child:ListTile(onTap:()=>widget.onPlay(i+1),title:Text('Episode ${i+1}'),trailing:const Icon(Icons.play_circle_outline,color:appPurple))))])))]));}
